#include <iostream>
#include <vector>
using namespace std;

int longest_common_subsequence(const vector<int>& word1, const vector<int>& word2) {
    int N = word1.size();
    int M = word2.size();

    // Initialize the DP table
    vector<vector<int>> dp(N + 1, vector<int>(M + 1, 0));

    // Fill the DP table
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= M; j++) {
            if (word1[i - 1] == word2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    // The answer is in dp[N][M]
    return dp[N][M];
}

