  const pulseLine = document.querySelector('.pulse-line');
  const container = document.querySelector('.pulse-animation');
  const containerWidth = container.offsetWidth;
  const dotWidth = pulseDot.offsetWidth;

  let isPulsing = false;
  let currentPos = 0;

  function moveDot() {
    if (currentPos + dotWidth >= containerWidth) {
      currentPos = 0;
    } else {
      currentPos += 2; // Adjust the speed here
    }

    pulseDot.style.left = `${currentPos}px`;

    if (Math.random() > 0.9 && !isPulsing) { // Randomly decide to pulse
      isPulsing = true;
      pulseDot.style.transform = 'translateY(-50%) scaleY(4)'; // Increase height to 32px (8px * 4)
      setTimeout(() => {
        pulseDot.style.transform = 'translateY(-50%) scaleY(1)'; // Return to original size
