### Node.js Example with Proper Error Handling

Here is an example of how you can modify the `sendMessage` function to include proper error handling using both `.catch()` and `async/await` with `try/catch`:

#### Using `.catch()`

```javascript
const { Client } = require('whatsapp-web.js');
const puppeteer = require('puppeteer');

// Initialize the client
const client = new Client({
    puppeteer: { headless: true }
});

client.on('ready', () => {
    console.log('Client is ready!');
});

// Function to send a message
function sendMessage(chatId, message) {
    return client.sendMessage(chatId, message)
        .then(() => {
            console.log(`Message sent to ${chatId}: ${message}`);
        })
        .catch((error) => {
            console.error(`Error sending message to ${chatId}:`, error);
        });
}

// Example usage
client.initialize().then(() => {
    sendMessage('123456789@c.us', 'Hello, this is a test message!');
});
```

#### Using `async/await` with `try/catch`

```javascript
const { Client } = require('whatsapp-web.js');
const puppeteer = require('puppeteer');

// Initialize the client
const client = new Client({
    puppeteer: { headless: true }
});

client.on('ready', () => {
    console.log('Client is ready!');
});

// Function to send a message
async function sendMessage(chatId, message) {
    try {
        // Attempt to send the message
        await client.sendMessage(chatId, message);
        console.log(`Message sent to ${chatId}: ${message}`);
    } catch (error) {
        // Handle any errors that occur during message sending
        console.error(`Error sending message to ${chatId}:`, error);
    }
}

// Example usage
client.initialize().then(async () => {
    await sendMessage('123456789@c.us', 'Hello, this is a test message!');
});
```

