import android.os.Bundle;
import android.util.Log;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;

import androidx.appcompat.app.AppCompatActivity;

import com.jcraft.jsch.ChannelExec;
import com.jcraft.jsch.JSch;
import com.jcraft.jsch.Session;

public class MainActivity extends AppCompatActivity {

    private Button btnUp;
    private EditText txtAddress;
    public static String wifiModuleIp;
    public static int wifiModulePort;
    public static String CMD;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        btnUp = findViewById(R.id.btnUp);
        txtAddress = findViewById(R.id.ipAddress);

        btnUp.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Set the wifiModuleIp and wifiModulePort variables to the Raspberry Pi's IP address and SSH port, respectively
                wifiModuleIp = "192.168.1.100";
                wifiModulePort = 22;

                // Set the CMD variable to the command to execute the Python script
                CMD = "python /path/to/script.py";

                // Execute the command on the Raspberry Pi using SSH
                Soket_AsyncTask task = new Soket_AsyncTask();
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                    task.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);
                } else {
                    task.execute();
                }
            }
        });
    }

    private class Soket_AsyncTask extends AsyncTask<Void, Void, String> {

        private static final String USER = "pi";
        private static final String PASSWORD = "your_password"; // Consider using key-based authentication
        private static final int TIMEOUT = 10000;

        @Override
        protected String doInBackground(Void... voids) {
            try {
                JSch jsch = new JSch();
                Session session = jsch.getSession(USER, wifiModuleIp, wifiModulePort);
                session.setPassword(PASSWORD);
                session.setConfig("StrictHostKeyChecking", "no");
                session.connect(TIMEOUT);

                ChannelExec channelExec = (ChannelExec) session.openChannel("exec");
                channelExec.setCommand(CMD);
                channelExec.setInputStream(null);
                channelExec.setErrStream(System.err);

                InputStream in = channelExec.getInputStream();
                channelExec.connect();

                byte[] tmp = new byte[1024];
                StringBuilder output = new StringBuilder();
                while (true) {
                    while (in.available() > 0) {
                        int i = in.read(tmp, 0, 1024);
                        if (i < 0) break;
                        output.append(new String(tmp, 0, i));
                    }
                    if (channelExec.isClosed()) {
                        if (in.available() > 0) continue;
                        break;
                    }
                    try {
                        Thread.sleep(1000);
                    } catch (Exception ee) {
                    }
                }

                channelExec.disconnect();
                session.disconnect();

                return output.toString();
            } catch (Exception e) {
                e.printStackTrace();
                return "Error: " + e.getMessage();
            }
        }

        @Override
        protected void onPostExecute(String result) {
            // Handle the result here
            Log.d("Soket_AsyncTask", "Result: " + result);
        }
    }
}
```

### Security Best Practices

1. **Use Key-Based Authentication**: Instead of using passwords, use key-based authentication for SSH. This is more secure and avoids the risk of password interception.
2. **Limit User Privileges**: Run commands with the least privilege necessary. Avoid running commands as the root user unless absolutely required.
3. **Input Validation**: Validate all input data to prevent injection attacks. Ensure that the IP address and command are sanitized and validated.
4. **Logging and Monitoring**: Enable logging and monitoring on the Raspberry Pi to detect and respond to suspicious activities.
5. **Regular Updates**: Keep the Raspberry Pi and all installed software up to date with the latest security patches.
6. **Firewall Configuration**: Configure the firewall to allow only necessary ports and connections. Block unnecessary incoming and outgoing traffic.
7. **Rate Limiting**: Implement rate limiting to prevent brute-force attacks on the SSH service.

### Example of Key-Based Authentication

To use key-based authentication, you need to generate an SSH key pair and copy the public key to the Raspberry Pi. Here’s how you can do it:

1. **Generate SSH Key Pair**:
   ```sh
   ssh-keygen -t rsa -b 4096 -C "your_email@example.com"
   ```

2. **Copy Public Key to Raspberry Pi**:
   ```sh
   ssh-copy-id pi@192.168.1.100
   ```

3. **Modify the Code to Use Key-Based Authentication**:
