```cpp
// Game.cpp
#include "Game.h"
#include <fstream>

Game::Game() : currentPlayer("White"), gameOver(false) {
    board.initialize();
    rating.loadFromFile("rating.txt"); // Load existing ratings
}

void Game::start() {
    board.initialize();
    currentPlayer = "White";
    gameOver = false;
    notify(); // Notify observers to update the UI
}

void Game::makeMove(int fromX, int fromY, int toX, int toY) {
    board.setPiece(toX, toY, board.getPiece(fromX, fromY));
    board.setPiece(fromX, fromY, "");
    currentPlayer = (currentPlayer == "White") ? "Black" : "White";
    if (/* check if game is over */) {
        gameOver = true;
        saveRating(player1, player2, currentPlayer == "White");
    }
    notify(); // Notify observers to update the UI
}

bool Game::isGameOver() const {
    return gameOver;
}

void Game::saveRating(const std::string& player1, const std::string& player2, bool player1Wins) {
    if (player1Wins) {
        rating.addWin(player1);
        rating.addLoss(player2);
    } else {
        rating.addWin(player2);
        rating.addLoss(player1);
    }
    rating.saveToFile("rating.txt");
}

void Game::setPlayerNames(const std::string& player1, const std::string& player2) {
    this->player1 = player1;
    this->player2 = player2;
}

std::string Game::getPlayer1() const {
    return player1;
}

std::string Game::getPlayer2() const {
    return player2;
}
