```cpp
// UI.cpp
#include "UI.h"
#include <iostream>

UI::UI(Game& game) : game(game), window(sf::VideoMode(800, 600), "Chess"), font(), text() {
    if (!font.loadFromFile("arial.ttf")) {
        std::cerr << "Could not load font\n";
    }
    text.setFont(font);
    text.setCharacterSize(24);
    text.setFillColor(sf::Color::White);
    game.attach(this); // Register UI as an observer
}

void UI::run() {
    while (window.isOpen()) {
        handleEvents();
        window.clear();
        drawBoard();
        drawButtons();
        window.display();
    }
}

void UI::drawBoard() {
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            sf::RectangleShape square(sf::Vector2f(100, 100));
            square.setPosition(i * 100, j * 100);
            square.setFillColor((i + j) % 2 == 0 ? sf::Color::White : sf::Color::Black);
            window.draw(square);
        }
    }
}

void UI::drawButtons() {
    sf::RectangleShape button(sf::Vector2f(200, 50));
    button.setFillColor(sf::Color::Blue);

    // Player Rating Button
    button.setPosition(300, 550);
    sf::Text buttonText("Player Rating", font, 24);
    buttonText.setFillColor(sf::Color::White);
    buttonText.setPosition(310, 560);
    window.draw(button);
    window.draw(buttonText);

    // Settings Button
    button.setPosition(300, 610);
    buttonText.setString("Settings");
    buttonText.setPosition(330, 620);
    window.draw(button);
    window.draw(buttonText);
}

void UI::handleEvents() {
    sf::Event event;
    while (window.pollEvent(event)) {
        if (event.type == sf::Event::Closed) {
            window.close();
        }
        if (event.type == sf::Event::MouseButtonPressed) {
            if (event.mouseButton.button == sf::Mouse::Left) {
                int x = event.mouseButton.x;
                int y = event.mouseButton.y;
                if (x >= 300 && x <= 500 && y >= 550 && y <= 600) {
                    showRating();
                } else if (x >= 300 && x <= 500 && y >= 610 && y <= 660) {
                    displaySettings();
                }
            }
        }
    }
}

void UI::displaySettings() {
    sf::RenderWindow settingsWindow(sf::VideoMode(400, 300), "Settings");
    sf::Text playerName1("Player 1 Name:", font, 24);
    sf::Text playerName2("Player 2 Name:", font, 24);
    sf::Text aiOption("Play against AI:", font, 24);

    sf::InputText inputPlayer1Name("", 20, font);
    sf::InputText inputPlayer2Name("", 20, font);
    sf::CheckBox checkBoxAI(false, sf::Vector2f(20, 20));

    playerName1.setPosition(10, 10);
    playerName2.setPosition(10, 60);
    aiOption.setPosition(10, 110);
    inputPlayer1Name.setPosition(220, 10);
    inputPlayer2Name.setPosition(220, 60);
    checkBoxAI.setPosition(220, 110);

    while (settingsWindow.isOpen()) {
        sf::Event event;
        while (settingsWindow.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                settingsWindow.close();
            }
            inputPlayer1Name.handleEvent(event);
            inputPlayer2Name.handleEvent(event);
            checkBoxAI.handleEvent(event);

            if (event.type == sf::Event::MouseButtonPressed && event.mouseButton.button == sf::Mouse::Left) {
                int x = event.mouseButton.x;
                int y = event.mouseButton.y;
                if (x >= 220 && x <= 380 && y >= 150 && y <= 200) {
                    game.setPlayerNames(inputPlayer1Name.getText(), inputPlayer2Name.getText());
                    settingsWindow.close();
                }
            }
        }

        settingsWindow.clear();
        settingsWindow.draw(playerName1);
        settingsWindow.draw(playerName2);
        settingsWindow.draw(aiOption);
        settingsWindow.draw(inputPlayer1Name);
        settingsWindow.draw(inputPlayer2Name);
        settingsWindow.draw(checkBoxAI);
        settingsWindow.display();
    }
}

void UI::displayRating() {
    sf::RenderWindow ratingWindow(sf::VideoMode(400, 300), "Player Ratings");
    sf::Text ratingText("", font, 24);
    ratingText.setFillColor(sf::Color::White);
    ratingText.setPosition(10, 10);

    std::ifstream file("rating.txt");
    std::string line;
    ratingText.setString("");
    while (std::getline(file, line)) {
        ratingText.setString(ratingText.getString() + line + "\n");
    }

    while (ratingWindow.isOpen()) {
        sf::Event event;
        while (ratingWindow.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                ratingWindow.close();
            }
        }
        ratingWindow.clear();
        ratingWindow.draw(ratingText);
        ratingWindow.display();
    }
}

void UI::update() {
    window.clear();
    drawBoard();
    drawButtons();
    window.display();
}

void UI::startGame() {
    game.start();
}

void UI::showRating() {
    displayRating();
}
