        return;
    }

    if (!is_user_logged_in()) {
        return;
    }

    $user_id = get_current_user_id();
    $artiste_posts = get_posts(array(
        'author' => $user_id,
        'post_type' => 'artiste',
        'numberposts' => 1,
    ));

    $artiste = $artiste_posts ? $artiste_posts[0] : null;

    if (isset($_POST['submit_artiste_form'])) {
        $post_data = array(
            'post_title' => sanitize_text_field($_POST['artiste_name']),
            'post_content' => sanitize_textarea_field($_POST['artiste_bio']),
            'post_status' => 'publish',
            'post_author' => $user_id,
            'post_type' => 'artiste',
        );

        if ($artiste) {
            $post_data['ID'] = $artiste->ID;
            $post_id = wp_update_post($post_data);
        } else {
            $post_id = wp_insert_post($post_data);
        }

        if ($_FILES['artiste_image']['size'] > 0) {
            $attachment_id = media_handle_upload('artiste_image', $post_id);
            set_post_thumbnail($post_id, $attachment_id);
        }
    }

    if (isset($_POST['delete_artiste_form']) && $artiste) {
        wp_delete_post($artiste->ID, true);
    }

    wp_redirect(add_query_arg('message', 'success', $_SERVER['HTTP_REFERER']));
    exit;
}
