```python
import threading

class Ticket:
    def __init__(self):
        self.MT = 1000
        self.next = 0
        self.lock = threading.Lock()

    def ticket(self):
        with self.lock:
            self.next = (self.next % self.MT) + 1
            return self.next

class Counter:
    def __init__(self):
        self.MT = 1000
        self.serve = 1
        self.condition = threading.Condition()

    def get_cheese(self, ticket):
        with self.condition:
            while ticket != self.serve:
                self.condition.wait()
            self.serve = (self.serve % self.MT) + 1
            self.condition.notify_all()
```

