BEGIN {
    FS = "\t";
    OFS = ", ";
}
$3 == "gene" {
    split($9, a, ";");
    for (i in a) {
        if (match(a[i], /^ID=gene:([^;]+)/, m)) {
            gene = m[1];
            break;
        }
    }
}
$3 == "exon" && gene {
    exon_count[gene]++;
}
END {
    for (g in exon_count) {
