// Initialize OpenSSL
void initOpenSSL() {
    SSL_load_error_strings();  // Load error strings for more readable error messages
    OpenSSL_add_ssl_algorithms();  // Add all SSL/TLS ciphers and digests
}

// Clean up OpenSSL
